-- 1) 345 → Trinity Global Excellence Postgraduate Scholarships, rel 10, upcoming, NULL/not_published
UPDATE scholarships SET title = 'Trinity Global Excellence Postgraduate Scholarships', provider = 'Trinity College Dublin', coverage_type = 'Tuition Credit', amount_usd_value = 0, deadline = 'Apply online after you hold a course offer for a full-time postgraduate taught programme: assessment is rolling, with regional final deadlines - for 2026/27 these were 1 April 2026 (Central, North and South America), 1 May 2026 (Africa), 15 June 2026 (all other regions, including Central Asia) and 15 July 2026 (South East Asia and Oceania). Those dates have passed and the next cycle''s deadlines were not yet published on the scheme page when this record was verified, so no deadline_date is recorded; early application is advised because awards are allocated on a rolling basis.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Master's"]$j$, eligible_majors = $j$["Full-time postgraduate taught programmes at Trinity College Dublin, EXCEPT courses in Business, Engineering, Natural Sciences and Computer Science & Statistics, which are exempt from this scheme (separate E3 and Trinity Business School scholarship routes cover those areas)"]$j$, eligible_countries = $j$["International applicants with non-EU fee status, billed at the non-EU rate, holding a TCD course offer - students from China are NOT eligible for this scholarship and are directed to the Claddagh Postgraduate Scholarship instead"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$Trinity's Global Excellence Postgraduate Scholarships are the university's flagship taught-postgraduate awards for international students: they go to exceptional international students who have received a course offer for a full-time postgraduate taught programme at Trinity College Dublin. Values range between EUR 2,000 and EUR 5,000 depending on the applicant's region, and each scholarship is applied as a one-time reduction to the tuition fees - a meaningful discount on the non-EU fee rather than full funding, so it should be budgeted as a partial offset, not a free degree. Eligibility is tightly framed: you must have non-EU fee status with fees billed at the non-EU rate and hold an offer to commence a full-time postgraduate degree programme; students from China are explicitly not eligible for this scheme (Trinity routes them to the Claddagh Postgraduate Scholarship instead), and courses in Business, Engineering, Natural Sciences and Computer Science & Statistics are exempt because those areas run their own scholarship routes (the E3 scholarships and Trinity Business School schemes). The application itself is light: an online form asking for basic personal information and a statement discussing how you will contribute to the Trinity College Dublin community (an alternative form is available from your Trinity Regional Manager if the online form is inaccessible in your region). Selection is rolling and based on academic achievement plus your potential to contribute to the Trinity community, with allocations also considering regional and programme diversity - which is why applying early matters. Successful applicants are contacted after their regional closing date (unsuccessful applicants are not contacted individually), must fully accept their course offer to receive the award, and have the scholarship applied directly to their tuition fee bill.$desc$, requirements = $req$Order of operations matters: first secure admission - you must hold a course offer to commence a full-time postgraduate taught (degree) programme at Trinity before applying, and your fee status must be non-EU at the non-EU rate. Two hard exclusions apply regardless of grades: students from China cannot use this scheme (the Claddagh Postgraduate Scholarship is the parallel route), and Business, Engineering, Natural Sciences and Computer Science & Statistics courses are exempt from the programme. The scholarship application is the online form linked from the scheme page: basic personal information plus a statement on how you will contribute to the Trinity community; if the form cannot be accessed in your region, your Trinity Regional Manager/Advisor can supply an alternative form. Applications are assessed and awarded on a rolling basis against academic achievement and contribution potential, with regional and programme diversity in the mix, and each region has a final deadline (in the published 2026/27 cycle: 1 April for the Americas, 1 May for Africa, 15 June for all other regions, 15 July for South East Asia and Oceania). If selected you must fully accept your course offer to receive the award; the money never reaches you as cash - it is credited against your tuition fee bill. No scheme-level GPA or IELTS cutoff is published (both belong to programme admission), so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.tcd.ie/study/international/scholarships/postgraduate/gexpg.php', source_url = 'https://www.tcd.ie/study/international/scholarships/postgraduate/gexpg.php', application_url = 'https://eu.surveymonkey.com/r/tges', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 115) from Trinity College Dublin's official 'Global Excellence Postgraduate Scholarships' page (study/international/scholarships/postgraduate/gexpg.php), fetched first-hand in full the same day. The stored hub URL (capitalised .../Postgraduate/) returned 403 to the fetcher; the scheme page itself loaded and states: scholarships for exceptional international students holding a course offer for a full-time postgraduate taught programme; value EUR 2,000-EUR 5,000 depending on region, applied as a one-time reduction to tuition fees; students from China are not eligible (Claddagh Postgraduate Scholarship instead); eligibility requires non-EU fee status billed at the non-EU rate and a course offer to commence a full-time postgraduate degree programme for academic year 2026/2027, with Business, engineering, natural sciences and computer science & statistics courses explicitly exempt (E3 scholarships and business.masters routes named instead); application via the online form (SurveyMonkey 'tges', stored as application_url) with basic personal information and a statement on contributing to the Trinity community, alternative form via the Regional Manager; selection rolling on academic achievement and contribution potential, with regional and programme diversity considered; regional final deadlines for 2026/27 - Africa 1 May 2026, Central/North/South America 1 April 2026, South East Asia and Oceania 15 July 2026, all other regions 15 June 2026; awardees must fully accept the course offer and the award is applied to the tuition fee bill; unsuccessful applicants are not contacted individually. Title corrected from the importer-style 'Trinity Global Excellence Postgraduate Award' to the official scheme name, and degree_levels corrected from [Master's, PhD] to [Master's] - the scheme is for taught postgraduate programmes only. deadline_date NULL/'not_published' with status 'upcoming': the published 2026/27 deadlines have passed and the next cycle's dates were not on the page. Award stored as NULL (EUR, 'one_time', 'variable') since the value varies by region within the EUR 2,000-5,000 band; amount_usd_value 0 (non-USD). university_scholarships row 535 synced; source 2625 repointed from the bare-domain placeholder to the scheme page. Previous record held the award at reliability 4 with no terms read.$note$, award_amount = NULL, award_currency = 'EUR', award_period = 'one_time', award_basis = 'variable', living_allowance = NULL, funding_type = 'One-time tuition-fee reduction of EUR 2,000-EUR 5,000 (value set by region) for non-EU offer-holders on full-time postgraduate taught programmes, awarded on a rolling basis', tuition_coverage = 'A single EUR 2,000-EUR 5,000 credit applied to the tuition fee bill - a partial discount against the non-EU fee, not full coverage.', english_requirements = 'No scholarship-level IELTS figure; English-language requirements belong to postgraduate programme admission.', required_documents = $j$["Course offer for a full-time postgraduate taught programme at Trinity College Dublin (required before applying for the scholarship)", "Online scholarship application form: basic personal information and a statement discussing how you will contribute to the Trinity College Dublin community (alternative form available from your Trinity Regional Manager if the form is inaccessible in your region)"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "2026/27 entry (published regional final deadlines)", "americas_deadline": "2026-04-01", "africa_deadline": "2026-05-01", "all_other_regions_deadline": "2026-06-15", "se_asia_oceania_deadline": "2026-07-15", "status": "closed"}, {"pattern": "Annual with rolling assessment: obtain a course offer first, then apply online early; regional final deadlines fall between April and July before autumn entry"}]$json$ WHERE id = 345 RETURNING id, title, source_reliability;

-- 2) 434 → University of Galway Global Scholarships (non-EU Excellence and Merit awards), rel 10, open, NULL/not_published, uni 283
UPDATE scholarships SET title = 'University of Galway Global Scholarships (non-EU Excellence and Merit awards)', provider = 'University of Galway', coverage_type = 'Partial Tuition', amount_usd_value = 0, deadline = 'No separate scholarship deadline is published on the scheme pages - the awards ride on course admission: merit amounts are attached to successful admission applications for listed programmes, and Excellence awardees must accept on the form provided within the stipulated acceptance window. Apply for your course early through the Global Galway application process; the current cycle is for Autumn 2027 entry and awards cannot be deferred to future years.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["Bachelor's", "Master's"]$j$, eligible_majors = $j$["Undergraduate and postgraduate taught programmes across the colleges - Business, Public Policy & Law (incl. Shannon College of Hotel Management), Science & Engineering, Arts, Social Sciences & Celtic Studies, Medicine & Health - with values and eligible-programme lists published per college/school"]$j$, eligible_countries = $j$["Non-EU applicants only. Additional region-based strands: IDEA (USA) 15% off tuition; 50% Latin America master's scholarships; region-based undergraduate packages of EUR 15,000-EUR 20,000 over 3-4 years for India, China, Vietnam, Brazil, Mexico, Thailand, Uganda and Turkey"]$j$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$Global Scholarships is the University of Galway's international non-EU scholarship programme - a merit scheme 'designed to attract and support outstanding students from around the world' - run as two families of awards across the colleges: Global Excellence scholarships and Merit scholarships (more than 280 were awarded last year). The amounts are set college by college. In the College of Science and Engineering's 2027/28 lists, most schools advertise merit awards of EUR 5,000 per year at undergraduate level 'for all successful applicants' on listed programmes, plus Excellence scholarships of EUR 10,000 per year (some per programme, Computer Science offers three); at postgraduate taught level the merit awards run at EUR 2,000, or EUR 2,000-EUR 5,000 on named programmes, again with EUR 10,000 Excellence awards. In the College of Business, Public Policy and Law, first-year undergraduates in the J.E. Cairnes School and the School of Law are listed at EUR 5,000, with region-based undergraduate packages of EUR 15,000-EUR 20,000 spread over three to four years for students from India, China, Vietnam, Brazil, Mexico, Thailand, Uganda and Turkey; at postgraduate taught level the headline is up to 50% of tuition - for one student per programme in J.E. Cairnes, and through the School of Law Global Scholarship for high-achieving students. Region strands cut across colleges: the IDEA Scholarship gives US applicants referred by IDEA (Philadelphia) 15% off tuition per year (three undergraduate places per college, automatically considered, notified soon after the offer), and there are 50% Latin America master's scholarships. The fine print matters: awards are partial fee waivers deducted from annual tuition fees only after at least 50% of the full fee has been paid; a student may hold only one Global Scholarship per year (a second offer, usually the lesser, is rescinded); the current cycle's awards are valid for Autumn 2027 entry only and cannot be deferred; multi-year awards continue only while each year is completed to the required progression standard; and Excellence scholars must accept inside the stated window. The Shannon College of Hotel Management and the remaining colleges publish their own Global Scholarships pages under the same programme.$desc$, requirements = $req$Be a non-EU applicant (the programme is explicitly restricted to applicants from non-EU countries) applying to an eligible undergraduate or postgraduate taught programme - each college page lists which programmes carry which award. For the merit amounts the colleges state them 'for all successful applicants' on the listed programmes, i.e. they are attached to the admission outcome rather than won through a separate scholarship competition on the pages read; the Excellence tier is selective, and if you are offered one you must accept it on the form provided within the stipulated acceptance window or lose it. Region strands have their own hooks: IDEA (USA) candidates must be referred by IDEA with the referral noted on the application form (then automatically considered, with notification soon after the offer), the region-based undergraduate packages are limited to the eight named countries, and the up-to-50% postgraduate awards in Business and Law point to school-level eligibility pages. Money mechanics: the waiver is deducted from your annual tuition fees, but only after you have paid the required minimum of 50% of the total tuition fee (not 50% of the post-scholarship balance); you may hold only one Global Scholarship in the year; awards for the current cycle are valid for Autumn 2027 entry only and cannot be deferred; and multi-year awards continue into later years only if you successfully complete each year to the required standard for progression. No single GPA or IELTS threshold is published at programme level - both sit inside course admission - so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.universityofgalway.ie/global-galway/globalscholarships/', source_url = 'https://www.universityofgalway.ie/global-galway/globalscholarships/', application_url = 'https://www.universityofgalway.ie/global-galway/studyinireland/howtoapply/ApplicationProcess.html', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-28 (cleanup pass 115) from the University of Galway's official Global Galway pages fetched the same day: the 'Scholarships for Global Students' hub (Global Scholarships framed as the university's international non-EU scholarship programme; Global Excellence and Merit Scholarships offered across the colleges), the Global Scholarships landing page (programme definition, college pages for Business Public Policy & Law, Shannon College of Hotel Management, Science & Engineering, Arts Social Sciences & Celtic Studies, Medicine & Health; 280+ scholarships awarded last year), the College of Science and Engineering and College of Business, Public Policy & Law college pages in their 'Global Scholarships 2027/2028' editions (CSE: undergraduate merit EUR 5,000 per year for all successful applicants in most schools and Excellence EUR 10,000 per year, postgraduate taught merit EUR 2,000 or EUR 2,000-EUR 5,000 with per-programme values, IDEA (USA) 15% with automatic consideration for IDEA-referred applicants, 50% Latin America masters scholarships; CBPL: EUR 5,000 for all first-year undergraduates in J.E. Cairnes and the School of Law, region-based undergraduate EUR 15,000-EUR 20,000 spread over 3-4 years for India, China, Vietnam, Brazil, Mexico, Thailand, Uganda and Turkey, up to 50% tuition for one postgraduate student per programme in J.E. Cairnes and up to 50% under the School of Law Global Scholarship, plus an 'Our Application Portal is Now Open' banner), and the Scholarship Terms & Conditions page for 2027/28 (non-EU applicants only; one Global Scholarship per student per year with the lesser second offer rescinded; partial fee waiver deducted from annual tuition fees after the required minimum 50% of the total tuition fee is paid; valid for Autumn 2027 entry only and not deferrable; Excellence acceptance on the form provided within the stipulated window; multi-year awards continue on successful progression). The previously stored URL (international-students/feesfunding/scholarships/) is dead (404) and its successor is this programme; no university-wide award named 'Global Achievement Award' appears on the fetched pages, so the record is re-anchored to the named Global Scholarships programme its hub URL identified. degree_levels corrected from [Master's, PhD] to [Bachelor's, Master's] - the programme covers undergraduate and postgraduate taught study (the hub's PhD routes are separate schemes such as Hardiman and the China Scholarship Council joint scheme). Award stored as NULL (EUR, 'year', 'variable') because values are college- and programme-specific tuition deductions; amount_usd_value 0. deadline_date NULL/'not_published' with status 'open' (application portal open for Autumn 2027 entry). university_id set to 283 (University of Galway) and university_scholarships row 702 created; source 2671 repointed from the bare-domain placeholder to the Global Scholarships landing page. Previous record held the programme at reliability 4 behind a dead URL with no terms read.$note$, university_id = 283, award_amount = NULL, award_currency = 'EUR', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'College-set partial fee waivers for non-EU students: merit awards of EUR 2,000-EUR 5,000 per year for successful applicants on listed programmes, Excellence awards of EUR 10,000 per year, and up to 50% of tuition on selected postgraduate taught programmes', tuition_coverage = 'A partial fee waiver deducted from annual tuition fees (after at least 50% of the full tuition fee has been paid); one award per student per year; multi-year awards continue on successful progression.', english_requirements = 'No scholarship-level IELTS figure; English-language requirements belong to course admission (Global Galway entry requirements).', required_documents = $j$["Course application via the Global Galway application process to an eligible undergraduate or postgraduate taught programme (published merit amounts attach to successful applications on listed programmes)", "Excellence awardees: accept the scholarship on the form provided within the stipulated acceptance window", "IDEA (USA) strand: referral by IDEA (Philadelphia) noted on the application form"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "2027/28 (Autumn 2027 entry)", "status": "open", "note": "Awards valid for Autumn 2027 entry only; cannot be deferred"}, {"pattern": "Annual and admission-driven: apply for the course; published merit amounts follow successful applications on listed programmes, Excellence awards are selective and time-limited to accept"}]$json$ WHERE id = 434 RETURNING id, title, source_reliability;

