UPDATE university_scholarships SET scholarship_name = 'Trinity Global Excellence Postgraduate Scholarships', availability_status = 'international_students', funding_type = 'One-time tuition-fee reduction of €2,000-€5,000 depending on region, for non-EU offer-holders on full-time postgraduate taught programmes (rolling assessment)', max_scholarship = '€2,000-€5,000 one-time tuition-fee reduction (value set by region)', eligibility_notes = 'Non-EU fee status with a course offer for a full-time postgraduate taught programme; students from China ineligible (Claddagh instead); Business, Engineering, Natural Sciences and Computer Science & Statistics courses exempt', official_url = 'https://www.tcd.ie/study/international/scholarships/postgraduate/gexpg.php', source_url = 'https://www.tcd.ie/study/international/scholarships/postgraduate/gexpg.php', verification_status = 'verified', last_verified_at = now() WHERE id = 535 RETURNING id;
INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES (702, 283, 434, 'University of Galway Global Scholarships (non-EU Excellence and Merit awards)', 'international_students', 'College-set partial fee waivers for non-EU students: merit €2,000-€5,000/yr for successful applicants on listed programmes; Excellence €10,000/yr; up to 50% of tuition on selected postgraduate taught programmes', 'Up to 50% of tuition (selected postgraduate taught programmes); Excellence €10,000/yr; merit €2,000-€5,000/yr', true, false, 'Academic merit: merit amounts attach to successful admission applications on listed programmes; competitive Excellence tier with a stipulated acceptance window', 'Non-EU applicants to eligible undergraduate/postgraduate taught programmes (per-college lists); one Global Scholarship per year; waiver applies after 50% of the full fee is paid; multi-year awards continue on successful progression', 'https://www.universityofgalway.ie/global-galway/globalscholarships/', 'https://www.universityofgalway.ie/global-galway/globalscholarships/', 'verified', now()) RETURNING id, scholarship_id;
